// Each entry is authored against local source pages; props describe a real artifact or rule model.
export const repairedLessons = {};
const courseNumber = (label,defaultValue,min=0,max=100) => ({label,default:defaultValue,min,max});
const courseDice = {dice:courseNumber('骰子数（双骰取平均）',1,1,2),threshold:courseNumber('达标门槛',4,1,6),prize:courseNumber('达标奖励',10,0,100),cost:courseNumber('每轮成本',4,0,100)};
const courseEconomy = {stock:courseNumber('甲的初始资源',100,0,1000),income:courseNumber('每人每轮产出',20),sink:courseNumber('每人每轮消耗',10),rounds:courseNumber('回合数',6,1,12),catchup:courseNumber('落后者补偿',0,0,20)};
const courseCurve = {a:courseNumber('开场',3,0,10),b:courseNumber('探索',5,0,10),c:courseNumber('受挫',4,0,10),d:courseNumber('高潮',8,0,10),e:courseNumber('尾声',3,0,10)};
function courseAdd(id,kind,pages,nav,concept,explanation,instruction,props={}) {
  repairedLessons[id]={nav,title:nav,pages:[...new Set(pages)].sort((a,b)=>a-b),lead:concept,idea:explanation,
    paragraphs:['本节练习为教学补充：'+instruction+' 保存后，再用下面的回忆问题把操作与原书概念连接起来。'],
    studio:{kind,title:nav,instruction,...props},prompts:[props.reflection||'刚才的'+nav+'中，哪一项变化最关键？用自己的操作结果解释它，并指出一个需要验证的限制。'],
    review:{prompt:props.reflection||'不看讲解，说明'+nav+'的关键关系，再给一个自己的例子。',answer:explanation},revision:3};
}
const courseBuild = (id,pages,nav,concept,explanation,fields,reflection) => courseAdd(id,'builder',pages,nav,concept,explanation,'填写各部分，生成一份可回看的设计草稿。至少写出设计决定与理由；开放作品由你自评。',{fields,reflection});
const courseGraph = (id,pages,nav,concept,explanation,nodes,reflection) => courseAdd(id,'graph',pages,nav,concept,explanation,'选择起点与终点，解释关系并添加至少两条连线。移除或重建关系，观察结构怎样变化。',{nodes,fields:['这条关系怎样发生？','整个关系图需要验证什么？'],reflection});
const courseOrder = (id,pages,nav,concept,explanation,cards,reflection) => courseAdd(id,'order',pages,nav,concept,explanation,'用上下按钮重排结构，再解释为什么这样安排。没有唯一正确顺序；保存的是你的方案。',{cards,fields:['我的排序理由与取舍'],reflection});
const courseCase = (id,pages,nav,concept,explanation,scenario,actions,reflection) => courseAdd(id,'case',pages,nav,concept,explanation,'在有限预算内组合方案；先看付出的代价，再写出你放弃了什么与下一次怎样验证。',{scenario,budget:6,actions:actions.map(([title,cost,consequence])=>({title,cost,consequence})),fields:['我选择这个方案的理由','舍弃的方案与下一次验证'],reflection});

courseGraph('hologram',[100,103,106],'皮肤与骨骼因果图','#10 全息设计：把体验与底层元素一起看。','玩家报告的是感受，设计师还需要查找造成感受的机制、故事、美学与技术因素。因果连线只是待检验解释；不能从一次抱怨直接证明原因。',['规则','故事','视觉与声音','技术','玩家感受'],'把一条体验抱怨连接到可能原因，怎样确认这条关系？');
courseBuild('tetrad',[101,102,103],'四元素协同简报','#9 四种元素：机制、故事、美学、技术共同支持体验。','作者把四元素视为互相影响的整体，显露程度不同不代表重要程度不同。先写共同的体验目标，再检查每一元素的贡献及不协调处。',['机制与目标','故事与事件','美学与感官','技术与载体'],'若删掉其中一个元素，你的体验目标会怎样改变？');
courseCase('ripple',[103,104,105],'改变一个元素之后','四元素之间的关系要在设计修改中检验。','技术限制可能改变美学和机制，叙事变化也可能影响玩家行为。下面使用另一个教学情境，让你做自己的协同修改，不把预设文字当成模拟结果。','你要为纸上潜行游戏适配没有声音的场景。',[['用可见警戒标记',2,'可读性提高，但需要解释标记含义。'],['重写听声寻路规则',3,'改变信息来源，需要重新试玩。'],['添加角色旁白卡',2,'补叙事线索，也增加阅读负担。']],'你修改了哪种元素，其他元素需要作什么补偿？');
courseBuild('diagnostic',[105,106],'全息诊断记录','#10 全息设计要求同时关注享受与分心。','诊断应分开记录可观察现象、对原因的推测、准备尝试的修改。玩家说不好玩不等于已经找到哪个元素有问题。',['具体体验现象','可能的元素原因','最小改动与验证方式'],'哪一条是事实，哪一条还只是你的假设？');
courseCase('themeFilter',[110,113],'让细节支持主题','#11 统一：各元素应向共同的主题发挥作用。','统一主题帮助设计师判断哪些细节增强目标体验、哪些使注意力分散。取舍依赖具体主题，没有适用于所有游戏的自动聚焦分数。','主题是“独自守护一盏夜灯”，你有六单位制作时间。',[['风声与摇晃灯影',2,'强化孤独与不确定。'],['合作派对排行榜',3,'可能转向竞技社交，需要解释它与主题的关系。'],['修灯的资源选择',3,'让守护成为实际行动。']],'你保留的细节如何共同支持主题？');
courseGraph('sensoryTheme',[110,111,113],'感官与主题连接图','主题可以通过不止一种感官表达。','作者鼓励让细节和主题互相支撑。感官内容并非越多越好；要判断它是否表达了同一体验，以及是否干扰操作。',['守护','灯光','风声','触感','修理动作'],'哪条感官线索支持主题，哪条可能干扰它？');
courseBuild('truth',[114,115,116],'把真相写进规则','主题可以来自体验，也可以来自你想表达的真相。','作者通过迪士尼等设计例子讨论主题的力量。表达一个真相不能只靠台词宣告；故事、行动和结果也应承载它。',['我想表达的真相','让玩家亲历的规则','可能产生相反理解的地方'],'玩家通过什么行动感到你的主题，而不是只听到它？');
courseBuild('resonance',[116,117],'共鸣与待验证的感受','#12 共鸣：关注设计是否触及玩家的深层感受。','共鸣需要设计者倾听自己的感受，也需要观察不同玩家。不要把自己的偏好当成共同结论；为想要的感受提出可实际验证的情境。',['让我产生共鸣的时刻','可能触发感受的细节','另一位玩家的反馈与待验证问题'],'自己的共鸣为什么不能代表所有受众？');
courseBuild('inspiration',[120,121,122],'生活灵感转化卡','#13 无尽灵感：从生活经验中寻找设计材料。','潜意识可以从非游戏的活动中获得线索。记录一段经历的结构、感觉或冲突，再把它变成一个可试的游戏行为；没有固定发酵天数能保证灵感。',['一段非游戏经历','其中的感觉或关系','转化成的动作与纸上原型'],'你借用了经历中的什么，而不是只换了一层题材？');
courseBuild('problemStatement',[123,124],'重新陈述设计问题','#14 问题陈述：先明确要解决的问题。','一个具体问题能让意识和潜意识更有效地寻找方案。把受众、目标体验与约束说清楚，并检查你是否把预先喜欢的解决方法误当成问题。',['谁遇到了什么问题','目标体验与约束','不预设解决方法的重新陈述'],'这段陈述是在说问题，还是偷偷指定了答案？');
courseGraph('brainstorm',[125,128,130,132],'自己的创意碰撞图','发散阶段先增加可能性，再进入筛选。','本章介绍多种头脑风暴方法。组合不同材料可能产生意外关系，但关联仍需变成可执行的动作与规则，才有机会被试玩检验。',['动作','对象','冲突','场景','意外规则'],'两条组合关系形成了什么能实际试玩的新点子？');
courseCase('ideaFilter',[133,135,139],'创意筛选与原型成本','筛选创意要看它能否服务目标与接受检验。','在发散之后可通过约束缩小范围。不要因为点子容易描述或自己喜欢，就认为它已经好玩；把最关键的不确定性转成一个低成本试验。','你有六单位时间，准备验证两人桌游的核心乐趣。',[['纸卡角色交换',2,'快速暴露互动是否有趣。'],['先制作完整美术',5,'提高展示质量，但较难检验核心选择。'],['招募三组目标玩家',3,'获得不同参与者的观察。']],'你最先验证哪项不确定性，为什么？');
courseBuild('eightFilters',[143,144,145],'八项测试证据板','#15 八项测试从美学、受众、设计、创新、商业、技术、社交和试玩检验创意。','各角度会对同一创意提出不同要求。自评分不是外部事实；记录每个判断的依据，再识别哪些依赖尚未验证的假设。教育等目标还可能需要额外测试。',['最需要关注的测试角度','支持判断的证据','仍缺少的证据与下一次试玩'],'哪个判断有证据，哪个仍只是信心？');
courseOrder('loop',[149,150,152,154],'把迭代排成可执行循环','设计、原型、测试与分析互相反馈。','迭代让设计接受现实结果的修正。缩短周期只有在循环产生可检查的结果时才有意义；次数本身不保证最终质量。',['提出假设','制作最小原型','观察试玩','分析证据','调整并再测'],'你的顺序在哪一步把观察变成下次修改？');
courseBuild('riskMatrix',[154,155,156,157],'风险与粗糙原型计划','#16 风险消除：先测试可能让方案失败的不确定性。','原型的形式应回应风险。纸上规则适合验证选择，动画可能适合展示氛围；漂亮但不回答关键问题的原型也可能浪费时间。',['最危险的假设','最低成本原型','观察指标与停止条件'],'你的原型能否推翻假设，还是只能展示它？');
courseBuild('toyPassion',[159,160,164],'玩具与激情实践日志','#17 玩具与 #18 激情帮助设计师检查操作乐趣和自身投入。','可以先检查没有目标时交互是否值得玩，再检查自己是否仍愿意继续改进。激情是需要倾听的主观信号，不是系统可以自动算出的项目成功指数。',['去掉目标后仍值得玩的动作','让我愿意继续的具体原因','下一次小改动与休息安排'],'操作好玩与目标有意义，分别怎样检查？');
courseBuild('playerProfile',[168,171,176,177],'有证据的玩家画像','#19 玩家：设计时考虑目标受众。','年龄、经验、生活情境与玩游戏的目的都会影响设计。画像是待验证的描述，不应从身份标签推断所有人的偏好。',['目标玩家与使用情境','一条访谈或观察证据','据此作出的设计修改'],'哪条画像信息有证据，哪条仍待观察？');
courseGraph('lazzaroFun',[179,180],'八种游戏乐趣映射','勒布朗的八种乐趣包括感官、幻想、叙事、挑战、团队关系、探索、表达与服从。','原书用勒布朗的分类观察不同乐趣，并提醒这种清单不是唯一划分。同一玩法可以支持多种乐趣；应描述实际行为与体验之间的关系，再向玩家验证。',['感官','幻想','叙事','挑战','团队关系','探索','表达','服从','核心玩法'],'你的核心动作怎样同时支持或妨碍两类乐趣？');
courseGraph('bartleTypes',[180,181,182],'玩家动机坐标关系','巴特尔分类从行动/互动、世界/玩家两个方向分析动机。','成就、探索、社交与支配可作为理解参与行为的视角。它来自特定游戏背景，不能保证现代游戏中的每位玩家都只有一种固定身份。',['行动','互动','世界','玩家','自己的玩法'],'哪种关系解释了玩家行为？有什么不符合分类的例子？');
courseCase('empathyLab',[177,180,182,183],'换一个受众看乐趣','#20 乐趣：从玩家立场检查可享受的内容。','游戏能带来不同感官、探索、成就与社交乐趣。移情练习应依靠具体情境，避免把新手困难直接解释为能力不足。','试玩者第一次进入潜行关卡，看不懂警戒图标。',[['用一次安全示范',2,'减少初次解释压力，仍需观察迁移。'],['加长说明文本',2,'补规则文字，也可能提高阅读负担。'],['允许失败后快速重试',3,'减少重试代价，不保证首次理解。']],'你如何从观察而非偏见推导改动？');
courseAdd('flowChannel','curve',[192,193,194,195],'挑战节奏设计','#21 心流关注目标、反馈与挑战和技巧的关系。','兴趣起伏与心流不是同一个测量指标。下面只让你画出对一段挑战节奏的设想，再通过试玩检查哪里焦虑、无聊或专注。','编辑五个时刻的自评值，写出目标受众与检验方式。',{numbers:courseCurve,fields:['每个时刻的挑战与预期感受','怎样验证技能和挑战是否匹配']});
courseAdd('cognitiveLoad','memory',[186,187,188],'先观察，再回忆','注意力有限；同时呈现信息会影响你注意到什么。','本章讨论大脑的建模、注意与想象等过程。下面只比较自己的两轮回忆，熟悉程度和记录方式都可能影响结果，不能测得普遍工作记忆容量。','选择三项或六项线索，隐藏后填写回忆，再对照本轮线索。',{fields:['按顺序写出回忆到的物件']});
courseGraph('mentalModel',[185,186,187],'心智模型与规则预期','玩家通过有限线索建立对游戏的理解。','设计要检查现实经验与界面线索是否让玩家形成适用的模型。错误预期可能使行动失败；修正时需要区分线索问题与规则问题。',['现实经验','界面线索','玩家预期','实际规则','行动结果'],'哪条线索可能让玩家建立错误预期？');
courseBuild('flowDDA',[194,195,196,197],'难度调整的验证计划','保持专注需要观察挑战与技能的变化。','难度调整可以改变体验，但不能用一个滑块预测心流。记录何时观察玩家，何时修改挑战，以及修改可能损害公平或成就感的地方。',['观察到的挑战与技能','准备调整的条件和幅度','公平、成就感与验证方式'],'自动变简单会在什么情况下损害体验？');
courseGraph('sdtNeeds',[200,201,202],'需求与玩法连接图','#22 需求包含马斯洛层次与胜任、自主、关联等视角。','需求模型帮助设计师询问游戏满足了什么。玩家可以同时追求多种需求，不能据一个画像自动预测长期热爱或留存。',['胜任','自主','关联','自我表达','核心动作'],'哪条规则满足了需求，哪条只是对需求作出承诺？');
courseCase('intrinsicVsExtrinsic',[202,203,204,205],'内外动机的取舍','#23 动机：内在与外在之间存在连续区间和转化。','本章讨论奖励有时会削弱原有兴趣，也讨论动机内化。不能推论外部奖励总是有害；应检查玩家如何理解活动、奖励和控制。','你希望玩家继续探索关卡，预算为六单位。',[['自主选择探索路线',3,'把选择留给玩家，需确保选择有意义。'],['每次探索给固定积分',2,'提供外部认可，需检查是否挤压探索本身。'],['分享发现给朋友',3,'增加表达与关联，也可能带来压力。']],'怎样区分奖励支持兴趣与奖励控制行为？');
courseOrder('noveltyLens',[206,207],'新奇与熟悉的安排','#24 创新：检查新内容为什么值得学习。','熟悉结构能帮助理解，新变化能重新吸引注意。原书没有给出固定的80/20最佳比例；安排应根据具体玩法与受众观察。',['熟悉规则','尝试小变化','安全反馈','组合新规则','独立应用'],'你为何安排这一处新变化，怎样知道它没有造成理解障碍？');
courseBuild('judgmentFairness',[207,208],'让评断有依据','#25 评断关注玩家希望获得怎样的评价。','结果应能让玩家理解自己的表现及改进方向。公平不只由分数决定，评价的可信度、对象与呈现方式都需要检查。',['被评价的技能','能观察到的证据','评价规则及争议处理'],'随机结果为什么可能不足以证明玩家能力？');

courseAdd('spaceTimeState','machine',[210,215,217,219],'事件驱动的状态机','#26 功能空间、#27 时间、#28 状态机帮助描述游戏的信息与变化。','状态不是装饰标签：同一事件在不同状态中可以产生不同结果。用对象、属性、可能取值与事件明确规则，能暴露不应发生的状态转移。','编辑巡逻、警戒、追击的转移表。连续执行至少三个事件，比较修改前后的路径。');
courseGraph('secretsEmergence',[222,224],'谁知道什么，行动作用于什么','#29 秘密与 #30 自发关注信息分布和行动组合。','隐藏信息会改变决策；基础动词作用于不同对象可以形成派生行动。涌现不是自动由规则少产生的，必须让组合实际可行并观察玩家如何利用。',['玩家甲','玩家乙','系统','公开目标','隐藏手牌','交换行动'],'改变一条信息或行动关系后，可能产生什么新策略，怎样检验？');
courseBuild('actionsRulesGoals',[225,226,231,232],'可执行规则说明','#31 行动、#32 目标、#33 规则必须连接起来。','玩家可执行的基础动作与派生动作不同。说明目标还不够，规则要明确何时允许行动、产生什么变化，以及怎样判断完成；程序、玩家约定和说明文字也应一致。',['基础动作与作用对象','目标及可检查的完成条件','允许、禁止与状态变化'],'写下一个非法动作，规则怎样阻止它？');
courseAdd('skillProbability','probability',[234,248,250],'骰子：均值相同，波动不同','#34 技巧、#35 期望值与 #36 概率帮助分析风险。','期望值是大量重复下的加权平均，不是对下一轮的保证。单骰与双骰平均值的均值相同，但分布和方差不同；门槛、奖励与成本一起决定期望净收益。','改变骰子数与奖励条件，抽样20次。至少比较两种设置，并用理论值解释样本差异。',{numbers:courseDice});
courseAdd('dominantStrategies','payoff',[258,261,263],'检查选择是否被支配','#37 公平、#38 挑战与 #39 有意义的选择关注玩家的机会与判断。','如果一种行动在所有情境都不更差且至少一个情境更好，其他行动可能失去价值。收益表能帮助检查这一问题，但真实游戏还存在技巧、信息与成本差异。','修改保守策略加成，比较是否出现被支配的行；保存两种有差异的表。',{numbers:{bonus:courseNumber('保守策略的统一加成',0,0,8)}});
courseAdd('triangleMethod','probability',[264,265,267,268],'收益与风险的可计算取舍','#40 三角形、#41 技巧与概率、#42 头与手提示不同取舍。','安全的小回报和风险大的回报可以构成有意义的选择。只比较期望值会忽略波动和失去资源的承受力；操作与思考的要求也要考虑玩家。','改变门槛、奖励和成本，比较两套规则的期望与样本。此模型只有随机性；请另写真实游戏如何加入技巧。',{numbers:courseDice});
courseAdd('feedbackLoops','economy',[269,270,274,277],'补偿规则改变差距','#43 竞争、#44 合作、#45 竞争与合作、#46 奖励、#47 惩罚提示体验取舍。','奖励和惩罚可以改变行动意义；反馈也能改变领先与落后者的关系。下面只模拟固定资源产出和落后补偿，不代表真实玩家的合作或竞技行为。','调整落后补偿和消耗，观察六回合内的差距。解释保持悬念与奖励表现之间的取舍。',{numbers:courseEconomy});
courseAdd('economyFaucets','economy',[279,281,282,284,288,289],'资源产生与消耗','#48 简单/复杂、#49 优雅、#50 性格、#51 想象力、#52 经济系统与 #53 平衡共同提示系统取舍。','产出与消耗会改变资源存量。游戏经济还包含交换、价值、玩家行为等因素；这里的模型只回答资源是否积累、耗尽或改变差距。优雅不是删除一切个性，复杂也不等于深度。','修改每轮产出与消耗，保存两种资源轨迹；指出模型未包含的一个重要因素。',{numbers:courseEconomy});
courseAdd('ahaMoment','puzzle',[292,294,295],'亲自解开一个灯阵','谜题让玩家停下来思考其可解决的结构。','顿悟与执行不是同一过程。一个能操作的玩具帮助玩家探索规则，目标清晰和局部变化有助于建立可解决感；下面用灯阵体验这些关系，不测量顿悟快感。','目标是让九盏灯全灭。观察点击的作用范围；可以请求一条可执行提示，解开后保存操作数与提示数。');
courseBuild('accessibilityProgress',[296,298,299,300],'为谜题设计入口与进展','#54 可达性与 #55 可见进步关注玩家能否开始、能否看见前进。','可达性不等于直接给答案，可见进展也不保证每一步都接近解。原书还强调可解决感与逐步增加难度；检查玩家如何形成这些预期。',['玩家第一步能操作什么','怎样显示进展与可解决感','逐步增加难度的方案'],'让玩家知道第一步，与让玩家知道全部答案，有什么区别？');
courseGraph('pyramidPuzzles',[301,302],'搭建平行谜题与汇聚结构','#56 平行性与 #57 金字塔减少单一瓶颈并把小答案汇成大挑战。','并行分支让卡住的玩家暂时切换任务，金字塔则让不同结果服务一个更大谜题。连线应标明依赖关系，而不是单纯增加分支数量。',['支线甲','支线乙','支线丙','共同线索','最终谜题'],'你的结构在哪里仍存在必须一次通过的瓶颈？');
courseOrder('puzzlePrinciples',[295,296,298,299,300,301,302,303,304],'按原书十原则检查谜题','#58 谜题：十原则是观察与取舍工具。','原书依次讨论目标清楚、容易上手、进步感、可解决感、逐步增加难度、平行性、金字塔、提示、给出答案，以及感知转移的利弊。原则不是统一评分表，给予提示或答案也可能帮助保留体验。',['目标清楚','容易上手','进步感','可解决感','逐步增加难度','平行性','金字塔结构','适时提示','给出答案','感知转移的取舍'],'哪三项原则最适合刚才的灯阵，为什么？');
courseAdd('interfaceTransparency','interface',[308,312,313],'映射能否被直接理解','#59 控制、#60 物理界面、#61 虚拟界面与 #62 透明关注玩家和游戏之间的联系。','界面应帮助玩家形成正确预期并执行行动。透明不是禁止所有界面，而是减少界面成为体验障碍的时刻。下面比较无提示与明确动作映射，不把成功次数当成沉浸评分。','完成三次目标动作，切换映射方式再试；记录自己如何判断按钮含义。');
courseAdd('juicinessLab','interface',[316,317,319],'输入之后，反馈改变了什么','#63 反馈与 #64 多汁关注动作是否获得可理解且丰富的回应。','反馈告诉玩家发生了什么，也影响动作的感觉。丰富反馈可能让输入更鲜活，但多并不总是更合适；应观察它是否干扰目标和节奏。','比较无提示与明确反馈模式。可点击播放短音，记录计数、动画与声音分别传达什么。');
courseGraph('primitiveChannels',[320,321,325],'把信息映射到感官通道','#65 原始性与 #66 通道和维度帮助思考直观动作及信息传递。','需要先识别玩家必须知道的数据，再决定通过视觉、声音、触觉或动作怎样表达。不能把某种音效或颜色当作对所有人的固定生理反应。',['生命状态','方向','危险','视觉','声音','动作'],'哪两条信息竞争同一通道？如何避免混淆？');
courseAdd('modesConsistency','interface',[326,327,329],'同一按钮为何做了不同事情','#67 模式：同一输入在不同状态下可能有不同含义。','模式有时能简化复杂界面，但若玩家没发现模式变化，就会按旧规则操作。应检查提示、状态边界与能否合并模式。','先完成明确映射三次，再切换交换左右模式重试。比较点错与预期，说明需要怎样提示模式变化。');
courseAdd('interestCurveModel','curve',[334,336,341,342],'把时刻画成兴趣曲线','#68 时刻与 #69 兴趣曲线关注体验如何随时间变化。','兴趣曲线可用来安排整段体验，也可嵌套到一关或一次挑战。开场、发展、高潮与收束是分析手段，不能保证每个玩家对同一形状都满意。','给五个时刻赋予自己的值，描述每个时刻发生什么，保存曲线后修改一处并比较。',{numbers:courseCurve,fields:['五个时刻分别发生什么','这一段曲线怎样通过试玩验证']});
courseBuild('inherentInterest',[342,343],'内部兴趣的具体来源','#70 内部兴趣：检查内容本身为何吸引人。','本章讨论风险、好奇、期待和不确定等因素。题材可能提供初始吸引，但它不能替代具体时刻的设计，也不能用题材名自动计算转化率。',['一个吸引人的内容或事件','它产生期待与不确定的原因','让兴趣进入玩家行动的方式'],'如果去掉题材外观，内容还剩什么吸引力？');
courseAdd('beautyClimax','palette',[344,345],'比较同一场景的表达','#71 美丽提醒设计师观察各元素怎样形成审美体验。','美丽不仅指视觉精细程度，也涉及声音、结构与整体表达。下面只比较配色的真实变化，并由你记录感受；它无法自动测得崇高或情感强度。','切换场景配色，描述一处目标可读性的差别和一处个人感受。',{fields:['我看到的具体变化','我的感受与想进一步修改的地方']});
courseBuild('projectionBlank',[346,347,348,349],'给玩家留下投影空间','#72 投影：玩家可能把想象与自己的一部分放入体验。','留白能给想象空间，但如果缺少足够线索也可能让人无法理解。用具体角色或场景检查哪些部分需要交代，哪些部分可由玩家补充。',['必须交代的线索','留给玩家补充的部分','怎样观察玩家的理解与代入'],'你的留白怎样既可理解又允许想象？');

courseGraph('storyDuality',[352,354,356],'让规则产生故事','#73 故事机器：事件可以由玩家与规则共同产生。','线性叙事可以预先安排事件，交互则让玩家行动影响发生什么。检查行动、结果和对结果的解释，看看系统是否提供值得讲述的经历。',['玩家目标','行动','规则','意外结果','故事'],'哪条规则可能产生不同于预设剧情的故事？');
courseBuild('storyMachine',[360,361,363],'目标、障碍与解决','#74 障碍与 #75 简单和超越提供故事结构视角。','目标与阻碍让事件具有冲突。清晰结构可以帮助玩家理解，超越熟悉结构的变化则需要建立在具体角色和体验上，不能只堆砌转折。',['角色追求的目标','迫使角色行动的障碍','行动结果与超出预期的变化'],'障碍怎样改变玩家可做的事，而不只是阻止前进？');
courseOrder('storyObstacles',[361,363,364],'给冲突安排层次','故事障碍应与角色目标及玩家体验连接。','每次阻碍都更大不是唯一有效节奏。可以安排发现、选择、代价与解决，让玩家理解自己的行动为何重要。下面的卡片为教学补充，可按自己的故事重排。',['确立目标','遇到阻碍','发现信息','付出代价','重新选择','解决冲突'],'你的顺序怎样让冲突产生意义，而非重复拖延？');
courseBuild('heroJourney',[365,370,372],'结构是工具，故事仍需成立','#76 英雄的旅程、#77 最奇怪的东西与 #78 故事提供不同检查角度。','熟悉的故事结构可以帮助构思，但作者提醒要检查故事中的奇怪之处及整体逻辑。不能把每个故事都强塞进固定阶段，也不能以结构齐全证明它感人。',['适合借用的故事阶段','最奇怪却缺少解释的地方','玩家行动与故事结构怎样协调'],'哪项结构需要偏离，为什么？');
courseAdd('indirectControl','map',[375,377,380,384,385],'通过线索引导行走','#79 自由、#80 帮助与 #81 间接控制关注玩家怎样自愿行动。','间接控制可以利用目标、界面、视觉、角色、声音等线索引导，而不是每次强制限制行动。引导应与玩家预期协调；本练习的着色只改变线索，不会自动移动玩家。','先关闭路线，从入口走到出口；打开路线再试，记录路径变化与自己的感受。');
courseGraph('stringOfPearls',[374,375,376],'开放片段与主线依赖','串珠是把较开放的段落串进整体进展的结构。','局部自由与整体安排可以同时存在。用关系图检查哪些结果是必须的，哪些活动可以自由安排；原书没有名为“#78 串珠结构”的独立透镜。',['入口','开放区域甲','主线节点','开放区域乙','终点'],'哪条依赖真的必要，哪条只是设计者的习惯？');
courseCase('freedomIllusion',[375,384,385],'自由与限制的代价','#79 自由要求检查玩家的自由感与实际约束。','限制可以帮助组织体验，也可能破坏预期。用情境和清楚的规则说明边界，不代表所有心理障碍都比物理障碍更好。','你要阻止玩家过早离开港口关卡。',[['设置可见封锁闸',2,'边界明确，但可能使自由感下降。'],['让出港需要修好船',3,'把约束转成可完成的目标。'],['留下同伴求助线索',2,'引导自主选择，仍可能被忽略。']],'限制如何被玩家理解？如果玩家选择忽略线索怎么办？');
courseBuild('contextControl',[387,388,390],'同伴与环境的协同','#82 串通：角色、空间与体验可以共同支持引导。','角色动作与环境安排可以帮助玩家发现目标，但必须检查线索是否真能被看到。设计者知道正确路线，试玩者未必知道；应记录行为与解释之间的差别。',['同伴或环境给出的线索','预期玩家作出的行动','观察线索是否有效的方法'],'怎样发现线索根本没有被玩家注意到？');
courseGraph('transmediaWorld',[392,396,400],'世界跨媒介的一致规则','#83 幻想与 #84 世界关注玩家想进入怎样的地方。','一个世界可以容纳不同故事与媒介。跨媒介不等于重复同一剧情；要确定哪些规则与魅力必须保留，哪些表达可以随媒介改变。',['世界规则','游戏行动','小说视角','影像事件','玩家幻想'],'换一种媒介后，什么必须保持，什么应改变？');
courseBuild('icebergMystery',[395,396,397],'背景设定的可见与隐藏','世界的厚度可以来自未完全展开的历史。','未说出的背景可以引发想象，也可能造成理解断层。先判断玩家完成当前行动需要知道什么，再把其他设定转成可发现的证据。',['当前行动必须知道的事实','可探索发现的历史证据','暂时不说的设定及理由'],'隐藏的信息怎样服务探索，而非掩盖规则？');
courseOrder('environmentalStory',[397,398,399],'从物证推演事件','环境内容可以帮助玩家拼出世界中的经历。','场景里的物件位置与状态能支持一种解释，但不一定只有一个解释。下面的教学物证需要你自己排序，并标明事实与推测。',['门被从内侧锁上','桌上有两只杯子','墙上留着旧地图','地上有湿脚印','一封未送出的信'],'你的事件顺序有哪些证据，哪些只是猜测？');
courseBuild('worldConsistency',[399,400],'世界规则的反例检查','#84 世界要求关注世界的独特性、一致性和可探索内容。','先明确世界中的限制，再检查角色与环境是否遵守。如果某个例外存在，应让玩家有机会理解原因；不能把所有意外都消除成单调的一致。',['一条重要世界规则','一个看似违背它的事件','合理例外与需要补的线索'],'这个例外是在丰富世界，还是破坏理解？');
courseBuild('characterFunction',[407,409],'化身与角色功能','#85 化身与 #86 角色功能关注玩家的自我投射和角色职责。','角色不只要有外观，也要在体验中承担作用。玩家化身、导师、对手等角色可能提供不同信息和行动机会；先写它服务什么，再决定表现。',['玩家化身支持什么想象','一个配角的体验功能','角色功能进入机制的方式'],'角色离开游戏后，玩家会失去什么体验？');
courseBuild('characterDesire',[410,411],'特征如何进入行为','#87 角色特征：用具体特性帮助角色被理解。','标签本身不能使角色立体。特征应在行动、关系和取舍中可见，同时允许矛盾与变化，而不是让所有人物只执行单一公式。',['角色的一项特征','表现或反驳特征的行动','这项特征带来的代价'],'如果删掉形容词，角色行为仍能让人认出他吗？');
courseGraph('characterWeb',[412,413,414],'搭建角色关系网络','#88 人际关系环状图与 #89 角色网络检查角色之间的态度。','关系可以从敌意/友好、服从/支配等维度观察，也可以写出每名角色对其他人的看法。关系不一定对称；本图用有向连线表示这种差别。',['主角','导师','同伴','对手','旁观者'],'两人互相看待对方的方式为何可能不同？');
courseOrder('uncannyValley',[417,420,421],'地位与角色转变','#90 地位与 #91 角色转变帮助检查人物随经历怎样改变。','人物关系和地位的变化能使事件有分量。明确转变前后的行为差别和导致转变的经历，比单纯宣告角色成长更有用。',['低位求助','获得信任','作出艰难选择','承担代价','新的关系与地位'],'哪个事件使转变可信，哪个只是换了身份称号？');
courseAdd('spatialPsychology','map',[426,428,429],'空间布局改变可行路径','空间不仅容纳物件，也组织人的行动和观察。','关卡布局会改变可达区域、绕行和视线。下面用离散网格检查连通性，它不能预测真实建筑的情绪效果，也不包含三维视线。','编辑障碍，再从入口行走到出口。记录怎样保留连通性并改变路线。');
courseGraph('landmarkMap',[429,431,432],'地标、路径与世界规则','#92 内在矛盾提醒检查空间与世界是否相互支持。','玩家用可见线索理解地方与路线。为地标建立作用和关联，并检查布局是否违反了这个世界自己的规则；具体地标分类是教学整理，不另造原书透镜编号。',['入口','中心地标','主路径','隐蔽路径','出口'],'哪条路径线索与世界设定发生冲突？');
courseAdd('vistaOcclusion','map',[432,434,435,436],'让路线线索可见','#93 难以名状的特性提醒设计者关注地方的整体感觉。','遮蔽、揭示、尺度等可以帮助组织空间体验，但效果需要实际观察。此二维练习只比较障碍与线索，不假装模拟视野、心跳或建筑审美。','改变障碍与引导开关，走两条不同路线，再描述地图需要补充的实际场景信息。');
courseBuild('spatialWayfinding',[438,439,440],'寻路观察与改造计划','空间引导是否有效，要通过玩家行为检验。','设计者熟悉自己的地图，容易低估迷路。记录在哪里停顿、回头或误解线索，再确定是路径、目标、视觉还是规则问题。',['实际观察到的寻路卡点','需要改变的空间或线索','下轮如何验证是否改善'],'一次回头怎样区分探索意图与迷路？');
courseAdd('aestheticTone','palette',[442,444,445],'氛围的具体材料','#94 氛围：艺术内容帮助玩家感到自己属于这个世界。','作者结合已有透镜讨论美学，并新增氛围视角。氛围不是一个单独数值；要关注视觉、声音及它们与玩家行动的关系。','切换同一场景配色，把观察与个人感受分开记录。',{fields:['可直接观察的颜色差别','个人感受与目标氛围']});
courseGraph('visualHierarchy',[443,444,445],'让重要信息被看见','美学表达也需要服务玩家接收信息与行动。','危险、目标与背景不应只依赖设计者知道的含义。用图建立视觉对象与功能的关系，再考虑不同屏幕、色觉和注意力条件下的可读性。',['背景','目标','危险','文字','玩家行动'],'两条视觉信息怎样避免互相争夺注意力？');
courseBuild('soundDesign',[446,447,448],'声音设计说明','声音可以表达材质、事件、空间和氛围。','声音不应被固定成世界的某个百分比。决定它传递什么，并安排无声时的替代线索；实际感受需要在目标设备上听和测试。',['需要传达的事件或空间信息','声音与节奏的具体设想','无声或听觉受限时的替代线索'],'这个声音提供了什么视觉不能充分提供的信息？');
courseCase('aestheticMechanism',[448,449,450],'美学与玩法的制作取舍','美术和声音与机制一起塑造体验。','表达质量不能只看细节数量。有限资源下，应先确定哪些表现会帮助核心行动和主题，哪些装饰会提高成本或影响读懂规则。','你在制作快速反应的纸卡数字原型。',[['清晰区分可点击目标',2,'减少识别歧义，需实测可读性。'],['每次点击播放长动画',4,'表达更丰富，也可能拖慢反应节奏。'],['短音与简短闪光',3,'提供即时回应，仍应检查干扰。']],'你怎样让表达的节奏回应机制？');
courseGraph('socialDynamics',[452,453],'玩家之间的互动关系','其他玩家能够提供对手、伙伴、观众和社会认可。','多人体验不仅在屏幕里发生，也依赖参与者怎样接收信息、交流与比较。用有向关系图检查谁对谁做了什么，避免只把人数增加当作社交设计。',['玩家甲','玩家乙','观众','共同目标','比分'],'哪条关系能带来社交体验，哪条可能带来压力？');
courseCase('coopSynergy',[453,454],'合作是否真的有必要','合作可以来自共同目标、互补能力或需要交流的信息。','信息不对称是方法之一，不是所有合作必需的条件。检查单人是否可替代所有参与者，以及合作是否对每个人都公平。','你设计两人修桥关卡。',[['两人同时搬材料',2,'需要同步，但可能让行动较机械。'],['一人看图，一人搭建',3,'需要交流，也可能使一人长期被动。'],['两人可轮换职责',2,'增加参与机会，也增加规则说明。']],'怎样避免合作任务中有人只是旁观？');
courseBuild('partyCompetition',[453,454,455],'让竞争值得参与','其他玩家能让竞争中的技巧、判断与互动更有意义。','竞争需要清楚的比较条件，也要考虑新手与熟练者的差异。落后补偿可能保持悬念，但如果遮盖表现差异，也可能损害成就感。',['被比较的表现','新手与熟练者的参与机会','保持悬念的取舍与试玩方法'],'胜负结果怎样体现参与者的选择？');
courseBuild('socialIcebreaker',[455,456],'让旁观者理解比赛','#95 旁观：游戏如何被看、被讲述也影响多人体验。','旁观者需要知道目标、关键行动和结果。不能假设玩家知道的信息都对观众可见；也要防止公开信息破坏比赛中的秘密。',['观众必须理解的目标','能公开与必须隐藏的信息','帮助观众跟上关键时刻的方式'],'哪项公开信息可能破坏参赛者的公平？');
courseGraph('communityLifecycle',[461,463,468],'友谊、表达与社群','#96 友谊、#97 表达与 #98 社群关注人与群体的纽带。','共同游戏可以形成关系，但友谊不由排行榜自动产生。检查玩家怎样认识别人、表达自己、再次相遇，以及群体怎样形成自己的文化。',['新成员','熟悉伙伴','自我表达','共同活动','社群规范'],'哪两条关系帮助新成员进入已有群体？');
courseCase('griefingGovernance',[468,470,471],'对恶意破坏作出回应','#99 恶意破坏：需要考虑玩家怎样伤害其他玩家的体验。','治理需要清楚规则、报告与判断，也要考虑误判和滥用。下面的成本是教学约束，不意味着某措施能按固定比例减少恶意行为。','有人在合作关卡里故意阻挡新手。',[['增设退出与重组队伍',2,'帮助受影响者脱离情境，不处理责任归属。'],['加入举报与复核',3,'建立处理路径，需要防止恶意举报。'],['让善意协助可见',2,'强调群体规范，不能替代严重行为的处置。']],'你的方案如何同时保护受影响者并减少误判？');
courseBuild('userCreativity',[462,463,467],'表达与用户创作','#97 表达可以帮助玩家展示自己的身份与想法。','用户创作需要可理解的工具和适合分享的结构。允许创作也会带来权限、审核、发现和作者认可的问题；要把工具与社群规则一起考虑。',['允许玩家创作的内容','分享、发现与作者认可','风险边界与复核方式'],'哪项自由需要工具支持，哪项需要群体规则？');
courseOrder('communityRituals',[468,469,471,472],'一个成员如何留下来','#98 社群需要共同活动、交流与持续关系。','群体仪式可以创造归属，但也可能排除新人。下面重排成员参与路径，检查何时能表达、何时能获得回应，而非用积分判断归属感。',['看见共同活动','第一次参与','表达个人选择','获得回应','再次相遇'],'新成员在哪一步可能被既有圈子挡住？');
courseBuild('teamDiversity',[474,475,483],'跨工种翻译同一目标','#101 团队：合作需要共享理解与有效交流。','不同工种可能用相同词语表达不同意思。把目标体验转成各自能检查的工作结果，并约定如何发现相互依赖的问题。',['共同的体验目标','给程序、美术和策划的具体说明','一次确认理解的方法'],'怎样发现大家说的“流畅”不是同一件事？');
courseGraph('visionConsensus',[477,480,483],'热爱与团队依赖','#100 爱与 #101 团队关注投入、理解和共同工作。','本章强调投入作品及合作中的倾听。共识不能只靠宣告一致；需要让分歧可见，并检查不同成员的贡献如何支持共同目标。',['共同目标','程序','美术','设计','试玩证据'],'哪项依赖最容易被团队成员忽略？');
courseBuild('psychologicalSafety',[480,481,483],'一次可以推进工作的复盘','团队交流要帮助问题被发现和解决。','不同观点可能暴露重要风险。复盘应把事实、解释和下一步分开，而不是把设计失败简单归因于某人的态度；以下记录结构为教学迁移。',['本次可观察的问题','不同工种的解释','下一次小实验与负责人'],'怎样让分歧形成可验证的工作，而非相互说服？');
courseCase('burnoutDefense',[482,483,484],'有限工期下的团队取舍','团队产出取决于目标、沟通与可持续的工作安排。','下面把团队协作概念迁移到排期。预算只代表可用制作时间，不能预测疲劳、灵感或产出品质；应让范围和风险透明。','展示日临近，你只有六单位团队时间。',[['只完成核心玩法闭环',3,'缩小范围，较容易验证整体体验。'],['补齐所有装饰细节',5,'改善展示，可能挤压试玩时间。'],['预留一次团队试玩与修正',2,'暴露集成问题，也减少可做功能。']],'你怎样对团队说明本次舍弃的范围？');
courseBuild('documentEssence',[486,487,492],'文档服务谁','#102 文档：帮助记忆、交流和协作。','文档不是因为长或正式就有价值。先明确读者当前要作的决定，再选择需要记录的信息、表达形式和更新负责人。',['目标读者及要作的决定','必须记录的设计信息','更新负责人及失效条件'],'删掉哪一部分仍不影响读者行动？');
courseBuild('onePageGdd',[488,489,492],'一页核心设计说明','设计文档需要使方案可理解、可执行、可讨论。','短文档可以帮助聚焦，但一页不是自动质量标准。明确目标、循环和待验证问题，细节可链接到相应记录；不要为了压缩而隐去关键约束。',['目标体验与受众','核心行动、规则与循环','关键风险与下一次验证'],'别人只看这页，能做出什么最小原型？');
courseOrder('livingDocuments',[489,490,491],'让文档跟上改动','设计过程中的文档需要随理解变化更新。','保留旧决定的原因有助于协作，但旧内容应清楚标记状态。下面的版本路径为教学整理，可以按团队实际情况重排。',['提出修改','记录影响范围','更新设计说明','标记旧版本状态','确认相关成员已知'],'你在哪一步防止旧规则继续被当作现行规则？');
courseGraph('audienceTailored',[490,491,492],'读者与所需信息','同一设计的不同读者可能需要不同层次的说明。','程序实现、美术表达和制作排期需要相互关联，却不必都用相同文字呈现。建立读者与信息之间的关系，再检查哪个关键读者漏掉了。',['程序','美术','设计','制作协调','规则逻辑','表现参考'],'哪个读者需要图，哪个读者需要精确状态条件？');
courseBuild('playtestFiveQuestions',[494,496,498,508],'试玩五问观察单','#103 试玩测试：先明确为何、谁、在哪、什么及怎样测试。','观察真实行为比不断指导玩家更能暴露问题。测试目标、参与者与场地会影响可解释的结论；一次试玩不是对所有玩家的证明。',['测试目的、受众与场地','要观察的行为及记录方式','不提示玩家时的安全与结束条件'],'你的安排能回答哪一个设计问题？');
courseGraph('realRootCauses',[503,504,505,508],'表象、解释与验证','玩家的反馈有价值，但提出的修改不是唯一解决方案。','区分观察到的行为、玩家的话、设计者解释与验证方法。多个解释可能对应同一现象；用小改动或追问排除其他原因，而不是直接选最顺耳的答案。',['观察现象','玩家反馈','解释甲','解释乙','小实验'],'两种解释怎样用同一个小实验区分？');
courseCase('usabilityVsFun',[505,506,507],'先解决哪一种试玩阻力','理解操作与享受玩法是相关但不同的问题。','玩家玩不懂时难以判断玩法是否有趣；操作顺畅也不保证核心决策值得玩。下面用有限验证预算明确下一步，而非为玩家自动打乐趣分。','试玩中，玩家频繁点错，同时说“选择没意思”。',[['单独测试按钮映射',2,'先检查可用性，不证明玩法有趣。'],['改一组策略收益再试玩',3,'检验选择差异，但要控制操作条件。'],['追加精美开场动画',4,'改善展示，可能不回答当前问题。']],'怎样避免同时改太多因素，导致无法解释结果？');
courseOrder('feedbackActionLoop',[507,508,510],'从观察到下一轮验证','试玩结果应进入下一次设计循环。','优先级应根据影响与证据，而不是抱怨音量。明确修改想改变什么行为，并在下轮检查它是否发生，同时关注新的问题。',['整理观察','区分事实与解释','选择一个关键问题','作出最小修改','下一轮验证'],'哪一步让你可以发现改动其实没有帮助？');
courseGraph('technologyCanvas',[512,515,521],'技术能力怎样进入玩法','#104 技术关注媒介给设计提供和限制的能力。','技术变化可以支持新行动，但功能新不等于体验有价值。把硬件能力连到玩家的具体行动与目标，并说明限制。',['输入能力','显示能力','运算约束','玩家行动','目标体验'],'哪条技术能力没有实际服务玩家行动？');
courseBuild('hypeCycleMirage',[521,523,525],'水晶球与理想世界','#105 水晶球与 #106 理想世界帮助思考未来的技术与值得创造的改善。','未来判断有不确定性，理想设计也需要回到现实条件。先描述想要的体验及对世界的改善，再识别依赖的技术、成熟度与可替代方案。',['理想的玩家体验','技术依赖与未证实的预测','今天能验证它的替代原型'],'哪些是目前事实，哪些只是对未来的判断？');
courseCase('constraintsCreativity',[516,520,521],'限制下仍可验证的原型','技术约束可以帮助设计者聚焦重要体验。','限制本身不会自动创造好玩法。选择能保留关键行动的替代形式，让原型回答设计问题，而不是先实现全部技术设想。','你要验证空间协作，只有普通屏幕与六单位时间。',[['纸上共享地图',2,'保留讨论与路径选择。'],['制作完整三维场景',5,'表现更充分，但可能挤压协作测试。'],['分屏显示不同线索',3,'快速检查信息交流是否有价值。']],'哪项技术可以暂时替代，哪项是体验必需？');
courseOrder('pipelineVelocity',[522,523,526],'工具链与检验循环','技术选择也应考虑设计验证的速度与成本。','改变参数到能试玩之间的延迟，会影响迭代。不能仅用引擎名字证明开发效率；记录实际步骤和最慢的环节。',['修改规则','更新数据','生成可运行版本','试玩','记录与再修改'],'哪一步可以缩短，怎样保证没有牺牲验证质量？');
courseGraph('clientIdentity',[528,530,533],'谁是客户，谁是玩家','#107 客户：理解对方真正关心的目标。','客户和玩家可能不是同一方；决定购买、批准或投入资源的人也可能有不同诉求。明确双方关系与约束，避免凭角色名假定其动机。',['玩家','出资方','发行方','平台','设计团队'],'哪两项诉求可能冲突，需要怎样确认？');
courseBuild('clientAlignment',[530,531,533],'把诉求变成可检查目标','理解客户需要倾听问题与背后的原因。','先记录对方要求，再追问希望得到的结果；不要把一次会议中的方案当成唯一目标。将理解写成可共同检查的标准。',['客户提出的要求','要求背后的结果及证据','共同认可的检查标准'],'哪个要求可以用另一种方案满足？');
courseCase('expectationManagement',[532,533,534],'范围、时间与信任','客户合作需要让约束和取舍被理解。','把能交付的内容和风险讲清楚，有助于形成共同预期。下面是教学协商情境，不宣称任何谈判策略总能成功。','客户希望展示完整关卡，但你只有六单位时间。',[['交付可玩的核心片段',3,'能检验机制，范围较小。'],['制作完整外观演示',5,'表达全貌，不能代表真实进展。'],['共同确认延期风险',2,'增加透明度，需要双方接受取舍。']],'你怎样清楚区分可以玩的内容与概念展示？');
courseBuild('demoTransparency',[533,534],'一次可核对的进展演示','展示进展应帮助客户理解现状与下一步。','可以用实际原型讨论，但需要清楚标明哪些已实现、哪些仍是假设。固定每两周不是原书要求；频率应回应项目和沟通需要。',['已经可以操作的部分','尚未实现的内容与风险','下次共同检查的问题'],'客户可能把什么误认为已经完成？');
courseOrder('elevatorPitch',[538,539,541,548],'让概念容易被理解','#108 推销：展示应适合对象并传达独特价值。','标签、类比和图像可以帮助听众理解，但不能替代核心玩法与可信细节。按对象安排展示，先让对方知道是什么，再给足判断依据。',['游戏概念','目标受众','独特行动','可见演示','所需资源与下一步'],'这次展示中，哪一点最值得对方记住？');
courseBuild('demoShowcase',[541,542,548],'演示的体验脚本','展示本身也可以按体验设计。','安排引入、关键时刻、实机内容和结束请求，能帮助展示连贯。演示必须说明真实实现范围；图像和表演不应掩盖核心问题。',['开场与最重要的一句话','展示中实际发生的三个时刻','结束后的具体请求'],'你的演示在哪里真正证明玩法，而不是只描述它？');
courseBuild('pitchObjections',[543,544,545],'为提问准备可信依据','对方的问题可能打断预先安排的展示。','准备设计、预算、技术等细节，也要能承认不确定性。不要编造数据填补空缺；记录需要回去确认的内容与跟进方式。',['对方最可能问的问题','已有证据与需要承认的未知','备选方案与下一次确认'],'哪个回答需要证据，不能只靠自信？');
courseBuild('pitchPassion',[546,547,548,550],'一份可以反复演练的推销稿','投入和熟悉细节能支持推销，但不保证对方接受。','原书强调理解对象、展示准备和真诚投入。下面形成自己的稿件，并计划请人试听；评价依据应来自听众是否理解，而非自动感染指数。',['一分钟推销稿','希望听众能复述的内容','试听对象及反馈问题'],'听众复述与原意不同时，你会修改什么？');
courseAdd('businessModels','cashflow',[552,554,555,564],'成本、收入与利益','#109 利益：设计与商业目标需要一起考虑。','收入、成本和合作方的利益会影响游戏能否持续。下面只计算固定价格、固定购买人数与成本，不预测真实销量，也不包含平台抽成、税费和退款。','修改输入，计算一段时间内现金变化。保存两种条件，解释哪个假设最不确定。',{numbers:{upfront:courseNumber('一次性成本',1000,0,100000),monthlyCost:courseNumber('每月成本',200,0,10000),price:courseNumber('单份收入',20,0,1000),customers:courseNumber('每月购买人数（假设）',20,0,10000),months:courseNumber('月数',6,1,12)}});
courseCase('ethicalMonetization',[556,558,564],'付费方案的体验代价','商业安排应考虑玩家与其他参与方的利益。','付费方式会影响规则与体验，不应在设计末尾才加入。伦理判断也需要考虑可理解的价格、选择与公平；以下情境为教学迁移。','一款竞技游戏需要持续收入。',[['付费外观',2,'通常不直接改变胜负，但仍要检查展示压力。'],['直接购买战斗优势',3,'产生明确收入途径，也改变竞争条件。'],['清楚标价的内容扩展',3,'增加内容，需要解释分割范围。']],'方案怎样赚钱，又付出了什么体验代价？');
courseBuild('ltvCacLoop',[559,560,562,564],'商业假设与证据','商业推算中的人数、复购与成本应有来源。','生命周期收入和获客成本是教学补充视角。不能只写一个不等式就证明业务健康；要说明估计来自何处、哪些成本被遗漏以及怎样验证。',['收入与购买行为的假设','成本来源与被遗漏的项目','最低成本验证计划'],'最可能使你的估计失效的是哪个假设？');
courseGraph('sustainableEcosystem',[562,563,564],'把各方利益放进同一张图','#109 利益要求检查合作关系怎样持续。','玩家、开发者、发行者与其他参与方的需要可能一致也可能冲突。用关系图表达交换与代价，避免将利润或艺术价值当作唯一目标。',['玩家','开发团队','发行方','持续内容','收入'],'哪条交换关系是长期不能维持的？');
courseGraph('transformationalExperience',[566,568,574,581],'从体验到现实改变','#110 塑造性：游戏可能改变玩家的理解、感受或行为。','改变不一定来自明确教学，也不一定在游戏外持续。先描述目标改变，再连接产生体验的行动和真实生活中的证据；迁移需要检验。',['游戏行动','体验与反思','目标改变','现实行为','验证证据'],'哪条从游戏到现实的关系最需要证据？');
courseBuild('seriousGames',[570,572,573,581],'把学习目标放进玩法','有明确教育或训练目的的游戏也需要被愿意参与。','把知识放进文本或奖励答题，未必使核心玩法支持目标。决定玩家通过什么行动练习，再检查游戏外能否使用；医疗例子不构成疗效承诺。',['明确学习目标','必须使用目标能力的游戏行动','游戏外检验迁移的任务'],'赢得游戏是否可能完全绕开学习目标？');
courseOrder('habitFormation',[574,576,577,581],'改变之后怎样检验','塑造性设计需要关注改变是否发生及是否持续。','通关和积分不能自动证明现实习惯改变。下面是教学验证路径，不是保证形成习惯的方法；要记录未发生改变和其他可能因素。',['记录原有行为','参与游戏行动','反思体验','游戏外尝试','隔一段时间复查'],'什么证据可能表明你期待的改变没有发生？');
courseBuild('lastingLegacy',[578,580,582],'希望留下什么影响','游戏可能给玩家留下积极或消极的长期印象。','设计意图与实际影响应分开。把希望留下的东西说具体，再说明有哪些证据和可能的意外后果，不用宏大口号替代观察。',['希望留下的具体改变','可能的负面或意外影响','后续访谈与观察方式'],'设计者希望留下的影响与玩家实际记住的影响不同怎么办？');
courseBuild('designerPower',[584,586,588],'责任与证据','#111 责任：设计者需要思考自己对玩家的影响。','原书讨论游戏影响及设计者的责任。负责任的判断既要倾听价值取向，也要考虑证据、差异与不确定性，不能用一个数字决定良知。',['希望产生的影响','可能受影响的玩家与风险','需要搜集的证据与改进办法'],'哪种影响不能只依据你的设计意图判断？');
courseCase('darkPatternsDefense',[585,586,588],'参与意愿与操控的边界','将责任概念迁移到时间、奖励与付费安排。','以下情境是现代教学补充。提醒和奖励可能支持玩家目标，也可能造成压力；检查退出是否容易、代价是否清楚、选择是否可撤回。','你要安排连续活动，制作预算为六单位。',[['错过一天就失去全部积累',2,'可能制造持续压力，应检查玩家是否能自由退出。'],['可暂停并保留进度',3,'尊重生活节奏，也改变运营安排。'],['明确活动期限和奖励',2,'提高透明度，仍要检查奖励是否造成不适压力。']],'你怎样判断设计在支持目标，还是利用玩家不愿损失的心理？');
courseBuild('realLifeBalance',[586,587,588],'真实生活中的退出设计','玩家的游戏体验与其他生活需要并存。','设计可以提供清楚的停顿、保存和恢复方式。并非每个游戏都需要相同时间限制；应关注实际受众与可能的冲突。',['适合停下的自然节点','退出、保存与恢复方式','与真实生活冲突时的支持'],'玩家停下时是否承担了不必要的损失？');
courseBuild('conscienceTest',[587,588],'记录一次责任取舍','#111 责任是一组需要持续面对的问题。','你愿意亲友参与可以帮助反思，但不是对所有群体安全或合适的证明。记录不同人的风险与利益，明确你会改变什么及怎样听取反馈。',['一个有争议的设计决定','各方利益与可能伤害','决定、理由与重新审查条件'],'谁的观点没有被听见，你怎样补上？');
courseBuild('deepestTheme',[590,591],'现在值得投入的工作','#112 乌鸦与 ∞ 号秘密目的帮助你追问真正的目标。','原书最后要求设计者倾听自己的内心，辨认什么工作值得投入有限时间，以及自己为什么做它。这不是系统能评定的答案。',['我为什么想做游戏','目前最值得投入的目标','愿意放弃的工作及理由'],'你的当前项目怎样回应真正重要的目标？');
courseBuild('lens114Creation',[590,591],'制作自己的观察透镜','教学补充：创造自己的观察卡，不沿用作者编号。','这本书共有编号1—112以及∞号透镜。原创观察卡可以来自自己的经历，写明它让你看什么、问什么，以及可能忽略什么；它不是原书的第114号透镜。',['我的观察卡名称','它提出的三个设计问题','适用情境及盲点'],'这张卡帮助你看到什么，又可能让你忽略什么？');
courseOrder('continuousPractice',[590,591],'下一次实践的具体路线','目标需要进入你能够执行的行动。','把自己的目的连接到一个小原型、一次倾听和下一轮修改。路线可以调整；不要把阅读完成等同于实践能力已成熟。',['选择一个值得解决的问题','制作最小原型','邀请目标玩家','倾听并记录','根据证据修改'],'下一次实践中，哪一步最可能改变你目前的想法？');
courseBuild('masteryFarewell',[591,593,594],'回看学习，继续实践','结束一次阅读，不代表已经掌握全部设计工具。','回看实际作品和疑问，区分自己能解释的概念、只记得名称的概念，以及还没有实践的概念。原书告别鼓励设计者使用工具并继续交流。',['一个已经用于作品的概念及证据','一个仍解释不清的概念','下一次实践与复习计划'],'你用什么具体作品证明自己能够应用一个概念？');

